namespace Ordering;

/// <summary>Coordinates product return acceptance, refunds, logging and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly RestockLedger _restockLedger = new();
    private readonly ReturnAcceptanceService _acceptanceService;
    private readonly RefundService _refundService = new();

    public ReturnsHandler()
    {
        _acceptanceService = new ReturnAcceptanceService(_restockLedger);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _acceptanceService.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _acceptanceService.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refundService.Compute(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundService.Log(order, amount);

    public int Restock(Order order) =>
        _restockLedger.Restock(order);
}

internal sealed class ReturnAcceptanceService
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);
    private readonly RestockLedger _restockLedger;

    public ReturnAcceptanceService(RestockLedger restockLedger)
    {
        _restockLedger = restockLedger;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReferences.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restockLedger.AddPending(line.Sku, line.Quantity);
        }

        if (!_restockLedger.HasPendingItems)
            return "no returnable lines";

        _processedReferences.Add(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReferences.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity >= 1 &&
                line.Quantity <= 100 &&
                !string.IsNullOrEmpty(line.Sku))
            {
                return true;
            }
        }

        return false;
    }
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            refund += CalculateLineRefund(line.Quantity);
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _refundLog.Add(CreateLogEntry(order.Reference, amount));
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    private static decimal CalculateLineRefund(int quantity)
    {
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;

        return quantity * UnitRefund;
    }

    private string CreateLogEntry(string reference, decimal amount)
    {
        if (_refundLog.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}

internal sealed class RestockLedger
{
    private readonly Dictionary<string, int> _pendingBySku = new(StringComparer.Ordinal);

    public bool HasPendingItems => _pendingBySku.Count > 0;

    public void AddPending(string sku, int quantity)
    {
        _pendingBySku[sku] = _pendingBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (!IsValidLine(line.Sku, line.Quantity))
                continue;

            if (_pendingBySku.TryGetValue(line.Sku, out var pending) && pending > 0)
            {
                moved += pending;
                _pendingBySku[line.Sku] = 0;
            }
            else
            {
                _pendingBySku[line.Sku] = line.Quantity > 50
                    ? line.Quantity / 2
                    : line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }

    private static bool IsValidLine(string sku, int quantity) =>
        quantity > 0 && quantity <= 100 && !string.IsNullOrEmpty(sku);
}
